import { CHAIN } from './chain-config.js';

/** Total gas includes the Glamsterdam state reservoir; execution still has its own cap. */
export function miningGasBounds(chainId = CHAIN.id, timestamp = Math.floor(Date.now() / 1000)) {
  const glamsterdam = Number(chainId) === 11155111 && Number(timestamp) >= 1791294816;
  return glamsterdam
    ? { min: 30_000_000n, max: 30_000_000n }
    : { min: 10_000_000n, max: 16_000_000n };
}
